  const mobile=document.createElement('button');mobile.className='button mobile-menu-control';mobile.type='button';mobile.id='mobile-menu';mobile.textContent='Console navigation';mobile.setAttribute('aria-controls','console-nav');mobile.setAttribute('aria-expanded','false');
