    el('policy-content').innerHTML=governance('policies')+`<div class="study-grid"><div class="stack">${content}</div><aside class="stack">${card('Safe read boundary',`<p>No raw ConfigMap, credentials, policy source, arbitrary Rego inputs or unrestricted metadata is exposed. A sanitized read must preserve scope, provenance, revision and caller authorization.</p>`)}${card('Related evidence',`${link('#audit?case='+caseId,'Open related audit →')}<p>Audit visibility is separate from policy configuration ownership and approval rights.</p>`)}</aside></div>`+source('No backend policy catalog, browser editing permission or rollout/version guarantee is claimed. Scope rules are source-backed semantics, not a new configurable policy engine.');
