  function routeInfo(){const [path,query='']=(location.hash.slice(1)||'approvals').split('?');return {screen:path.split('/')[0],id:path.split('/')[1],query:new URLSearchParams(query),key:path};}
  function resetScreens(){for(const s of document.querySelectorAll('.main section[id^="screen-"]'))s.hidden=true;for(const a of document.querySelectorAll('.sidebar a'))a.removeAttribute('aria-current');for(const id of ['state-control','catalog-state-control','definition-control','inventory-state-control','inventory-visibility-control'])el(id).hidden=true;}
