    el('remaining-state-control').hidden=!handled;el('outcome-control').hidden=screen!=='verification';el('workspace-control').hidden=screen!=='investigation'||onlyApprovals;el('evidence-control').hidden=screen!=='review';
    if(!canReadView(screen)){el('dock').hidden=true;el('remaining-state-control').hidden=true;if(screen==='investigation'){el('composer').disabled=true;el('send-message').disabled=true;}denyRoute('This capability study permits independent approval review, not this operational read. No protected record or fallback is shown.');return;}
    if(screen==='investigation'&&!window.KubernautFixtureContext.workspaceForRoute(id)){el('dock').hidden=true;el('workspace-control').hidden=true;el('composer').disabled=true;el('send-message').disabled=true;denyRoute('No authorized existing-workspace relationship is supplied by the selected dataset. No demo workspace, agent or session is substituted.');return;}
    if(screen==='review'&&window.KubernautFixtureContext.dataset()!=='synthetic'){el('evidence-control').hidden=true;el('approve').disabled=true;el('deny').disabled=true;denyRoute('The recorded captures supply no independent readable RAR for this route. Use a recorded case, or explicitly select the synthetic safety study. No pending request is manufactured.');return;}
